113→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
114→  const { t } = useTranslation();
115→  return (
116→    <div className="message-bubble__segment message-bubble__segment--error">
117→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
118→      <div className="message-bubble__error-message">{errorMessage}</div>
119→      {onRetry && (
120→        <button className="message-bubble__error-retry" onClick={onRetry}>
121→          {t('tryAgain')}
122→        </button>
123→      )}
124→    </div>
125→  );
126→}
