128→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
129→  const { t } = useTranslation();
130→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
131→  const [isEditing, setIsEditing] = useState(false);
132→  const [editText, setEditText] = useState(message.content);
133→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
134→  const textareaRef = useRef<HTMLTextAreaElement>(null);
135→
136→  const isUser = message.role === 'user';
137→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
138→
139→  useEffect(() => {
140→    if (isEditing && textareaRef.current) {
141→      textareaRef.current.focus();
142→      textareaRef.current.selectionStart = textareaRef.current.value.length;
143→    }
144→  }, [isEditing]);
145→
146→  const handleEdit = () => {
147→    setEditText(message.content);
148→    setIsEditing(true);
149→    setIsConfirmingDelete(false);
150→  };
151→
152→  const handleCancelEdit = () => {
153→    setIsEditing(false);
154→    setEditText(message.content);
155→  };
156→
157→  const handleSaveEdit = () => {
158→    const trimmed = editText.trim();
159→    if (!trimmed || trimmed === message.content) {
160→      handleCancelEdit();
161→      return;
162→    }
163→    setIsEditing(false);
164→    editMessage(messageIndex, trimmed);
165→  };
166→
167→  const handleDeleteConfirm = () => {
168→    setIsConfirmingDelete(false);
169→    deleteMessage(messageIndex);
170→  };
171→
172→  const handleKeyDown = (e: React.KeyboardEvent) => {
173→    if (e.key === 'Escape') {
174→      handleCancelEdit();
175→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
176→      e.preventDefault();
177→      handleSaveEdit();
178→    }
179→  };
180→
181→  let streamingRemainder: string | undefined;
182→  if (hasSegments && message.isStreaming && message.content) {
183→    const segmentedText = message.segments!
184→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
185→      .map((s) => s.text || '')
186→      .join('');
187→    const remaining = message.content.slice(segmentedText.length);
188→    if (remaining.trim()) {
189→      streamingRemainder = remaining;
190→    }
191→  }
192→
193→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
194→  const isInAnswerPhase = message.currentPhase === 'answer';
195→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
196→
197→  const hasCharts = hasSegments && message.segments!.some(
198→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
199→  );
200→
201→  const answerBlockSegments = hasSegments
202→    ? message.segments!
203→        .filter((s) =>
204→          (s.type === 'answer' && s.text?.trim()) ||
205→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
206→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
207→          (s.type === 'subagent_end' && s.chart_spec)
208→        )
209→        .map((s) => {
210→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
211→            return { ...s, text: stripChartSpecBlocks(s.text) };
212→          }
213→          return s;
214→        })
215→        .filter((s) => {
216→          // Remove text segments that became empty after stripping chart blocks
217→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
218→            return false;
219→          }
220→          return true;
221→        })
222→    : [];
223→
224→  const questionSegments = hasSegments
225→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
226→    : [];
227→
228→  return (
229→    <div className={`message-bubble message-bubble--${message.role}`}>
230→      <div className="message-bubble__header">
231→        {isUser ? t('you') : t('assistant')}
232→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
233→          <span className="message-bubble__actions">
234→            <button
235→              className="message-bubble__action-btn"
236→              onClick={handleEdit}
237→              title={t('editMessage')}
238→            >
239→              &#9998;
240→            </button>
241→            <button
242→              className="message-bubble__action-btn message-bubble__action-btn--delete"
243→              onClick={() => setIsConfirmingDelete(true)}
244→              title={t('deleteMessage')}
245→            >
246→              &#128465;
247→            </button>
248→          </span>
249→        )}
250→      </div>
251→
252→      {isUser && isConfirmingDelete && (
253→        <div className="message-bubble__confirm-delete">
254→          <span>{t('deleteConfirm')}</span>
255→          <div className="message-bubble__confirm-actions">
256→            <button
257→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
258→              onClick={handleDeleteConfirm}
259→            >
260→              {t('delete')}
261→            </button>
262→            <button
263→              className="message-bubble__confirm-btn"
264→              onClick={() => setIsConfirmingDelete(false)}
265→            >
266→              {t('cancel')}
267→            </button>
268→          </div>
269→        </div>
270→      )}
271→
272→      {isUser && isEditing ? (
273→        <div className="message-bubble__edit-mode">
274→          <textarea
275→            ref={textareaRef}
276→            className="message-bubble__edit-textarea"
277→            value={editText}
278→            onChange={(e) => setEditText(e.target.value)}
279→            onKeyDown={handleKeyDown}
280→            rows={3}
281→          />
282→          <div className="message-bubble__edit-actions">
283→            <button
284→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
285→              onClick={handleSaveEdit}
286→            >
287→              {t('saveResend')}
288→            </button>
289→            <button
290→              className="message-bubble__edit-btn"
291→              onClick={handleCancelEdit}
292→            >
293→              {t('cancel')}
294→            </button>
295→          </div>
296→        </div>
297→      ) : hasSegments ? (
298→        <div className="message-bubble__segments">
299→          {!questionSegments.some((s) => !s.userAnswer) && (
300→            <ThinkingBlock
301→              segments={message.segments!}
302→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
303→              isThinkingPhase={isThinkingPhase}
304→              isAgentStreaming={!!message.isStreaming}
305→              hasAnswer={hasAnswer}
306→            />
307→          )}
308→          {questionSegments.map((seg, i) => (
309→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
310→              <UserQuestion
311→                questionData={seg.questionData!}
312→                userAnswer={seg.userAnswer}
313→                userFreeText={seg.userFreeText}
314→              />
315→            </div>
316→          ))}
317→          {answerBlockSegments.length > 0 && (
318→            <div className="message-bubble__segment message-bubble__segment--answer">
319→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
320→              {answerBlockSegments.map((seg, i) => {
321→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
322→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
323→                  return (
324→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
325→                      {seg.type === 'tool' && seg.toolResult ? (
326→                        <InlineQueryResult result={seg.toolResult!} />
327→                      ) : seg.chart_spec ? (
328→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
329→                      ) : null}
330→                    </div>
331→                  );
332→                }
333→                // Text segment (answer or subagent_end without chart_spec)
334→                return (
335→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
336→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
337→                  </div>
338→                );
339→              })}
340→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
341→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
342→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
343→                return displayText?.trim() ? (
344→                  <div className="message-bubble__segment-content">
